60: /** 解析工具的风险操作徽章 */
61: function getRiskBadge(toolName: string, riskDescription?: string): string {
62:   if (riskDescription) {
63:     if (riskDescription.includes('写入') || riskDescription.includes('修改数据')) return '写入操作';
64:     if (riskDescription.includes('Shell') || riskDescription.includes('命令')) return '系统命令';
65:     if (riskDescription.includes('网络') || riskDescription.includes('请求')) return '网络请求';
66:     if (riskDescription.includes('文件')) return '文件修改';
67:   }
68:   if (toolName.includes('create') || toolName.includes('record')) return '写入操作';
69:   if (toolName.includes('delete')) return '删除操作';
70:   if (toolName.includes('update') || toolName.includes('edit') || toolName.includes('write')) return '修改操作';
71:   if (toolName.includes('execute') || toolName.includes('bash') || toolName.includes('terminal')) return '系统命令';
72:   if (toolName.includes('http') || toolName.includes('search')) return '网络请求';
73:   return '高风险操作';
74: }
