15: /** 计划审批卡片：拉取任务计划书，由用户批准或拒绝后再执行。 */
16: export function PlanApprovalCard({
17:   sessionId,
18:   isSubmitting,
19:   onDecision,
20: }: PlanApprovalCardProps) {
21:   // null 表示加载中；空字符串表示没有计划书
22:   const [plan, setPlan] = useState<string | null>(null);
23: 
24:   // 挂载时读取计划书；组件卸载后忽略结果，避免内存泄漏告警
25:   useEffect(() => {
26:     let alive = true;
27:     fetchPlan(sessionId).then((content) => {
28:       if (alive) setPlan(content ?? '');
29:     });
30:     return () => {
31:       alive = false;
32:     };
33:   }, [sessionId]);
34: 
35:   return (
36:     <section className={styles.card} aria-label="任务计划书审批">
37:       <div className={styles.heading}>
38:         <ClipboardList size={18} aria-hidden="true" />
39:         <div>
40:           <p className={styles.title}>任务计划书待审批</p>
41:           <p className={styles.progress}>批准后 Agent 将按计划逐步执行</p>
42:         </div>
43:       </div>
44: 
45:       {plan === null ? (
46:         <div className={styles.loadingState}><LoadingTree size="small" label="正在读取计划书…" /></div>
47:       ) : plan === '' ? (
48:         <p className={styles.description}>暂无计划书内容</p>
49:       ) : (
50:         <div className={styles.details}>
51:           <ReactMarkdown remarkPlugins={[remarkGfm]}>{plan}</ReactMarkdown>
52:         </div>
53:       )}
54: 
55:       <div className={styles.actions}>
56:         <button
57:           type="button"
58:           className={styles.deny}
59:           disabled={isSubmitting}
60:           onClick={() => onDecision(false, false)}
61:         >
62:           <X size={15} aria-hidden="true" />
63:           拒绝
64:         </button>
65:         <button
66:           type="button"
67:           className={styles.allow}
68:           disabled={isSubmitting}
69:           onClick={() => onDecision(true, false)}
70:         >
71:           <Check size={15} aria-hidden="true" />
72:           {isSubmitting ? '正在提交…' : '批准执行'}
73:         </button>
74:       </div>
75:     </section>
76:   );
77: }

